/**
 * Bibliothèque ouverte élargie — ~2 760 variétés supplémentaires
 * dérivées d'un dataset public (grow_data, licence MIT, scrapé de
 * Wikileaf ; voir scripts/fetch_strains.py). Pour ces entrées, seul
 * le nom et le chimiotype (dérivé de la classification THC/CBD
 * publiée) sont retenus — pas de trait violet ni de fiche de culture,
 * faute de données fiables à cette échelle (voir README). Générées
 * une fois par le script, pas re-téléchargées à l'exécution.
 */
interface BulkStrainRaw {
  id: string;
  name: string;
  chemotype: ChemotypeId;
  autoflower: boolean;
}

function bulkToPreset(b: BulkStrainRaw): StrainPreset {
  const chemotypeLabel =
    b.chemotype === 'I' ? 'THC dominant' : b.chemotype === 'III' ? 'CBD dominant' : 'chimiotype mixte';
  return {
    id: b.id,
    name: b.name,
    chemotype: b.chemotype,
    autoflower: b.autoflower,
    violet: false,
    description: `${chemotypeLabel} (bibliothèque ouverte, non vérifiée)`,
    info: undefined,
  };
}

/** Bibliothèque complète pour la recherche (curatée + ouverte). Le
 * formulaire de plantation cherche dans cet ensemble ; STRAIN_PRESETS
 * seul reste la référence pour "Ajouter une variété" à la main. */
export const ALL_STRAIN_PRESETS: StrainPreset[] = [
  ...STRAIN_PRESETS,
  ...(bulkStrainsRaw as BulkStrainRaw[]).map(bulkToPreset),
];

export interface CannabinoidPhenotype {
  chemotype: ChemotypeId;
  /** Ratio THC-type / CBD-type au sein du profil cannabinoïde (0–1,
   * thc + cbd = 1 en chimiotype I/II/III ; les deux valent 0 en
   * chimiotype IV/V, voir `cbg`) — reflète la dominance allélique du
   * locus B, pas un taux de laboratoire. Sert au moteur de sélection
   * et à la teinte visuelle (résine ↔ anthocyane), jamais affiché tel
   * quel comme pourcentage de terrain (voir `thcPercent`/`cbdPercent`). */
  thc: number;
  cbd: number;
  /** Vaut 1 en chimiotype IV (synthases THCA/CBDA non fonctionnelles,
   * le CBG précurseur s'accumule sans être converti), 0 sinon. Pas un
   * ratio continu comme thc/cbd : en IV le profil est ~100% CBG parmi
   * les cannabinoïdes présents. */
  cbg: number;
  /** Taux de THC/CBD au sens d'une fiche d'analyse (% de matière
   * sèche), à afficher à l'utilisateur. Dérivés de la teneur totale
   * en cannabinoïdes de l'individu (`totalPotencyPercent`, réaliste :
   * ~8–28%) répartie selon le ratio `thc`/`cbd` ci-dessus — jamais de
   * valeur aberrante type "97% de THC", impossible en réalité. Valent
   * 0 en chimiotype IV/V. */
  thcPercent: number;
  cbdPercent: number;
  /** Taux de CBG en % de matière sèche — non nul seulement en
   * chimiotype IV. */
  cbgPercent: number;
  /** Vaut 1 en chimiotype VI (CBC-synthase active à maturité, cc —
   * juvénilité prolongée, voir l'en-tête du fichier), 0 sinon. Même
   * convention binaire que `cbg`. */
  cbc: number;
  /** Taux de CBC en % de matière sèche — non nul seulement en
   * chimiotype VI. */
  cbcPercent: number;
  /** Teneur totale en cannabinoïdes (THC + CBD, ou CBG en chimiotype
   * IV, ou CBC en chimiotype VI), % de matière sèche. Quasi nulle
   * (chanvre fibre) en chimiotype V. */
  totalPotencyPercent: number;
  /** true si l'individu est homozygote récessif pr/pr au locus
   * propyl/pentyl (voir l'en-tête du fichier) — ses cannabinoïdes sont
   * de la série "varin" (THCV/CBDV/CBGV/CBCV) plutôt que la série
   * pentyl classique. `thc`/`cbd`/`thcPercent`/etc. ci-dessus restent
   * calculés normalement (dominance/scoring inchangés) ; utiliser ce
   * drapeau + `thcvPercent`/`cbdvPercent`/`cbgvPercent`/`cbcvPercent`
   * pour l'AFFICHAGE du bon nom de molécule. */
  propylSeries: boolean;
  /** Miroirs de thcPercent/cbdPercent/cbgPercent/cbcPercent, non nuls
   * SEULEMENT si `propylSeries` — même valeur numérique, juste la
   * bonne étiquette de molécule (voir ci-dessus). */
  thcvPercent: number;
  cbdvPercent: number;
  cbgvPercent: number;
  cbcvPercent: number;
}

/**
 * Phénotype terpénique (chemovar) d'un individu — pourcentages
 * RELATIFS entre eux, parmi les 7 terpènes modélisés (somme ≈ 100%).
 * Ce ne sont PAS des pourcentages de matière sèche vérifiables comme
 * `thcPercent`/`cbdPercent` : aucune donnée labo de ce type n'existe
 * pour les variétés simulées (voir l'en-tête du fichier) — uniquement
 * une répartition relative utile pour comparer/sélectionner des
 * individus entre eux. Voir `BreedingEngine.terpeneProfile`.
 */
export interface TerpeneProfile {
  myrcenePercent: number;
  limonenePercent: number;
  pinenePercent: number;
  linaloolPercent: number;
  /** Dérivé du trait "sesquiterpene" — voir l'en-tête du fichier
   * (même enzyme TPS9 que l'humulène, ratio fixe ~2:1). */
  caryophyllenePercent: number;
  humulenePercent: number;
  /** Quasi nul (<1%) sauf en tt (`terpinoleneDominant`), où il domine
   * fortement le mélange — trait récessif rare, voir l'en-tête. */
  terpinolenePercent: number;
  /** true si l'individu est homozygote récessif tt au locus
   * Terpinolène. */
  terpinoleneDominant: boolean;
  /** Les 2 à 4 terpènes qui dépassent le seuil de dominance, triés du
   * plus au moins dominant — clés canoniques `TerpeneKey` (langue-
   * neutres), à traduire côté UI via `tEnum('terpene', clé)`. */
  dominantTerpenes: string[];
}

// --- RNG déterministe (mulberry32), pour des sessions reproductibles ----

export function mulberry32(seed: number) {
  let a = seed >>> 0;
  return function rng() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function sampleBetaLike(rng: () => number, mean: number, concentration = 12): number {
  // Approximation par affinement gaussien successif, bornée [0,1] —
  // suffisant pour restituer la dispersion attendue autour de la
  // moyenne du génotype sans dépendance à une librairie stats.
  let x = mean;
  const spread = Math.sqrt((mean * (1 - mean)) / (concentration + 1));
  for (let i = 0; i < 4; i++) {
    const u1 = Math.max(rng(), 1e-9);
    const u2 = rng();
    const gaussian = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    x = x + gaussian * spread * 0.5;
  }
  return Math.min(0.98, Math.max(0.02, x));
}

let counter = 0;
function nextId(prefix: string): string {
  counter += 1;
  return `${prefix}-${String(counter).padStart(4, '0')}`;
}

export function resetIdCounter() {
  counter = 0;
}

/** À appeler juste après le rechargement d'un état sauvegardé (voir
 * persistence.ts) : fait avancer le compteur d'ids au-delà du plus
 * grand suffixe numérique déjà utilisé parmi les individus restaurés,
 * pour qu'un nouvel individu créé après le chargement ne réutilise
 * jamais un id déjà présent dans l'état restauré. */
export function ensureIdCounterAbove(ids: string[]) {
  for (const id of ids) {
    const m = id.match(/-(\d+)$/);
    if (m) counter = Math.max(counter, parseInt(m[1], 10));
  }
}

/** Les trois traits polygéniques secondaires suivent tous la même
 * construction que la vigueur (loci additifs + bruit environnemental) :
 * hauteur, résistance au froid, et préférence lumineuse (ombre ↔ plein
 * soleil). On les traite génériquement via `QuantitativeTrait` plutôt
 * que de dupliquer trois fois le même code. */
type QuantitativeTraitId =
  | 'vigor'
  | 'height'
  | 'cold'
  | 'sun'
  | 'mold'
  | 'myrcene'
  | 'limonene'
  | 'pinene'
  | 'linalool'
  | 'sesquiterpene';

/** Seuil de dominance (% du mélange) au-delà duquel un terpène est
 * retenu dans `TerpeneProfile.dominantTerpenes`. */
const TERPENE_DOMINANCE_THRESHOLD = 10;

/** Fréquence par défaut de l'allèle T (normal) chez les fondateurs
 * générés aléatoirement — calée pour ~14% de tt (terpinolène
 * dominant) à l'équilibre, cohérent avec la distribution bimodale
 * documentée en littérature (voir l'en-tête du fichier). */
const DEFAULT_TERPINOLENE_T_FREQ = 0.63;

/** Fréquence par défaut de l'allèle C (normal) au locus CBC chez les
 * fondateurs générés aléatoirement — trait rare et spécialisé
 * (de Meijer et al. 2009), calée pour ~2-3% de cc (chimiotype VI) à
 * l'équilibre. Voir l'en-tête du fichier. */
const DEFAULT_CBC_C_FREQ = 0.85;

/** Taux de recombinaison (fréquence de crossing-over méiotique) entre
 * les loci PIGMENT (violet) et PROPYL (varin) — voir l'en-tête du
 * fichier pour l'avertissement important sur ce que représente cette
 * constante. 0 = loci totalement liés (toujours co-hérités ensemble),
 * 0,5 = ségrégation indépendante (aucune liaison, comportement
 * d'origine du moteur). 0,12 = liaison modérée choisie pour rendre le
 * phénomène visible dans un programme de sélection sur quelques
 * générations, sans être aussi extrême qu'une liaison totale. */
const PIGMENT_PROPYL_RECOMBINATION_RATE = 0.12;

export class BreedingEngine {
  private rng: () => number;
  private traitEffects: Record<QuantitativeTraitId, number[]>;

  constructor(seed: number = Date.now()) {
    this.rng = mulberry32(seed);
    const makeEffects = () => Array.from({ length: N_VIGOR_LOCI }, () => 0.4 + this.rng() * 2.1);
    this.traitEffects = {
      vigor: makeEffects(),
      height: makeEffects(),
      cold: makeEffects(),
      sun: makeEffects(),
      mold: makeEffects(),
      myrcene: makeEffects(),
      limonene: makeEffects(),
      pinene: makeEffects(),
      linalool: makeEffects(),
      sesquiterpene: makeEffects(),
    };
  }

  private randomHaplotype(trait: QuantitativeTraitId, freqHigh = 0.5): number[] {
    return this.traitEffects[trait].map((effect) => (this.rng() < freqHigh ? effect : 0));
  }

  private segregateHaplotype(hapA: number[], hapB: number[]): number[] {
    return hapA.map((_, i) => (this.rng() < 0.5 ? hapA[i] : hapB[i]));
  }

  private shufflePair<T>(pair: [T, T]): [T, T] {
    return this.rng() < 0.5 ? pair : [pair[1], pair[0]];
  }

  /** Tire une paire d'allèles Terpinolène indépendamment (équilibre de
   * Hardy-Weinberg), selon la fréquence de l'allèle T fournie — voir
   * l'en-tête du fichier (distribution bimodale documentée). */
  private randomTerpinolenePair(freqT: number): [TerpinoleneAllele, TerpinoleneAllele] {
    const draw = () => (this.rng() < freqT ? 'T' : 't');
    return [draw(), draw()];
  }

  /** Tire une paire d'allèles CBC indépendamment (équilibre de
   * Hardy-Weinberg), selon la fréquence de l'allèle C fournie — même
   * logique que `randomTerpinolenePair` (locus indépendant, voir
   * l'en-tête du fichier : chimiotype VI, trait rare). */
  private randomCbcPair(freqC: number): [CbcAllele, CbcAllele] {
    const draw = () => (this.rng() < freqC ? 'C' : 'c');
    return [draw(), draw()];
  }

  /** Construit les traits terpéniques normalisés (0–1) d'un individu à
   * partir de ses haplotypes — même construction que la vigueur
   * (`computeQuantitative` + normalisation par la borne théorique de
   * la session), voir l'en-tête du fichier. */
  private buildTerpeneTraits(haps: {
    myrceneHapA: number[];
    myrceneHapB: number[];
    limoneneHapA: number[];
    limoneneHapB: number[];
    pineneHapA: number[];
    pineneHapB: number[];
    linaloolHapA: number[];
    linaloolHapB: number[];
    sesquiterpeneHapA: number[];
    sesquiterpeneHapB: number[];
  }): TerpeneTraits {
    return {
      myrcene: this.percentOf('myrcene', this.computeQuantitative(haps.myrceneHapA, haps.myrceneHapB)) / 100,
      limonene: this.percentOf('limonene', this.computeQuantitative(haps.limoneneHapA, haps.limoneneHapB)) / 100,
      pinene: this.percentOf('pinene', this.computeQuantitative(haps.pineneHapA, haps.pineneHapB)) / 100,
      linalool: this.percentOf('linalool', this.computeQuantitative(haps.linaloolHapA, haps.linaloolHapB)) / 100,
      sesquiterpene:
        this.percentOf('sesquiterpene', this.computeQuantitative(haps.sesquiterpeneHapA, haps.sesquiterpeneHapB)) / 100,
    };
  }

  /** Détermine le chimiotype par épistasie entre les loci P, C, O et
   * B — voir l'en-tête du fichier. P (voie en amont) prime sur tout
   * (pp -> pas de CBGA disponible, donc pas de CBC non plus) ; ensuite
   * C (CBC-synthase, locus indépendant de B/O mais en compétition pour
   * le même CBGA) prime sur O (synthases), qui prime sur B (THC vs
   * CBD) : un individu pp est toujours chimiotype V même s'il porte
   * par ailleurs cc/oo/BT-BT. Ordre : P > C > O > B. */
  private resolveChemotype(
    bPair: [BAllele, BAllele],
    oPair: [SynthaseAllele, SynthaseAllele],
    pPair: [PathwayAllele, PathwayAllele],
    cPair: [CbcAllele, CbcAllele]
  ): ChemotypeId {
    if (pPair[0] === 'p' && pPair[1] === 'p') return 'V';
    if (cPair[0] === 'c' && cPair[1] === 'c') return 'VI';
    if (oPair[0] === 'o' && oPair[1] === 'o') return 'IV';
    const set = new Set(bPair);
    if (set.size === 1 && set.has('BT')) return 'I';
    if (set.size === 1 && set.has('BD')) return 'III';
    return 'II';
  }

  private computePhenotype(
    bPair: [BAllele, BAllele],
    oPair: [SynthaseAllele, SynthaseAllele],
    pPair: [PathwayAllele, PathwayAllele],
    cPair: [CbcAllele, CbcAllele],
    propylPair: [PropylAllele, PropylAllele]
  ): CannabinoidPhenotype {
    const chemotype = this.resolveChemotype(bPair, oPair, pPair, cPair);
    const propylSeries = propylPair[0] === 'pr' && propylPair[1] === 'pr';
    // Mêmes valeurs numériques que thcPercent/cbdPercent/etc., juste
    // recopiées sous le nom de molécule "V" quand pr/pr — voir la doc
    // de `CannabinoidPhenotype.propylSeries`.
    const varinMirror = (thcPercent: number, cbdPercent: number, cbgPercent: number, cbcPercent: number) =>
      propylSeries
        ? { thcvPercent: thcPercent, cbdvPercent: cbdPercent, cbgvPercent: cbgPercent, cbcvPercent: cbcPercent }
        : { thcvPercent: 0, cbdvPercent: 0, cbgvPercent: 0, cbcvPercent: 0 };

    if (chemotype === 'V') {
      // Chanvre fibre : voie de biosynthèse déficiente en amont du
      // CBGA lui-même — cannabinoïdes quasi indétectables (~0-2%).
      const totalPotencyPercent = Math.min(2, Math.max(0.05, sampleBetaLike(this.rng, 0.01, 30) * 100));
      return {
        chemotype,
        thc: 0,
        cbd: 0,
        cbg: 0,
        cbc: 0,
        thcPercent: 0,
        cbdPercent: 0,
        cbgPercent: 0,
        cbcPercent: 0,
        totalPotencyPercent: Math.round(totalPotencyPercent * 100) / 100,
        propylSeries,
        ...varinMirror(0, 0, 0, 0),
      };
    }

    if (chemotype === 'IV') {
      // Synthases THCA/CBDA inactives : le CBG (précurseur) s'accumule
      // sans être converti — teneur comparable à un profil I/II/III
      // classique, mais entièrement composée de CBG.
      const totalPotencyPercent = Math.min(20, Math.max(4, sampleBetaLike(this.rng, 0.1, 20) * 100));
      const cbgPercent = Math.round(totalPotencyPercent * 10) / 10;
      return {
        chemotype,
        thc: 0,
        cbd: 0,
        cbg: 1,
        cbc: 0,
        thcPercent: 0,
        cbdPercent: 0,
        cbgPercent,
        cbcPercent: 0,
        totalPotencyPercent: Math.round(totalPotencyPercent * 10) / 10,
        propylSeries,
        ...varinMirror(0, 0, cbgPercent, 0),
      };
    }

    if (chemotype === 'VI') {
      // CBC-synthase restée active à maturité (juvénilité prolongée,
      // cc) : capte le CBGA disponible à la place de THCAS/CBDAS —
      // teneur plausible en % de matière sèche, dans un intervalle
      // légèrement plus bas que le CBG (IV), cohérent avec un
      // chimiotype rare et moins documenté en littérature.
      const totalPotencyPercent = Math.min(15, Math.max(3, sampleBetaLike(this.rng, 0.08, 20) * 100));
      const cbcPercent = Math.round(totalPotencyPercent * 10) / 10;
      return {
        chemotype,
        thc: 0,
        cbd: 0,
        cbg: 0,
        cbc: 1,
        thcPercent: 0,
        cbdPercent: 0,
        cbgPercent: 0,
        cbcPercent,
        totalPotencyPercent: Math.round(totalPotencyPercent * 10) / 10,
        propylSeries,
        ...varinMirror(0, 0, 0, cbcPercent),
      };
    }

    const thc = sampleBetaLike(this.rng, CHEMOTYPES[chemotype].thcMean, 12);
    const cbd = 1 - thc;
    // Teneur totale en cannabinoïdes réaliste (fiche d'analyse type
    // seed-bank : ~8–28% de matière sèche, moyenne ~18%) — indépendante
    // du ratio THC/CBD ci-dessus, qui ne décrit que leur proportion
    // relative. Répartie ensuite selon ce ratio pour l'affichage.
    const totalPotencyPercent = Math.min(28, Math.max(8, sampleBetaLike(this.rng, 0.18, 20) * 100));
    const thcPercent = Math.round(thc * totalPotencyPercent * 10) / 10;
    const cbdPercent = Math.round(cbd * totalPotencyPercent * 10) / 10;
    return {
      chemotype,
      thc,
      cbd,
      cbg: 0,
      cbc: 0,
      thcPercent,
      cbdPercent,
      cbgPercent: 0,
      cbcPercent: 0,
      totalPotencyPercent: Math.round(totalPotencyPercent * 10) / 10,
      propylSeries,
      ...varinMirror(thcPercent, cbdPercent, 0, 0),
    };
  }

  private computeQuantitative(hapA: number[], hapB: number[]): number {
    const genetic = hapA.reduce((a, b) => a + b, 0) + hapB.reduce((a, b) => a + b, 0);
    const noise = (this.rng() - 0.5) * 1.6;
    return Math.max(0, genetic + noise);
  }

  /** Borne supérieure théorique d'un trait polygénique pour cette
   * session (tous les loci au maximum sur les deux haplotypes) — sert
   * à normaliser l'affichage en jauge/pourcentage. */
  private maxOf(trait: QuantitativeTraitId): number {
    return this.traitEffects[trait].reduce((a, b) => a + b, 0) * 2 + 0.8;
  }

  private percentOf(trait: QuantitativeTraitId, value: number): number {
    const max = this.maxOf(trait);
    if (max <= 0) return 0;
    return Math.max(0, Math.min(100, (value / max) * 100));
  }

  /** Borne supérieure théorique du trait de vigueur pour cette session. */
  maxVigor(): number {
    return this.maxOf('vigor');
  }

  createFounder(opts: {
    chemotype: ChemotypeId;
    sex: Sex;
    autoflower?: boolean;
    violet?: boolean;
    label?: string;
    vigorFreq?: number;
    heightFreq?: number;
    coldFreq?: number;
    sunFreq?: number;
    moldFreq?: number;
    /** Fréquence de l'allèle T (normal) au locus Terpinolène — défaut
     * 0,63 (~14% de tt/"terpinolène dominant" à l'équilibre, voir
     * l'en-tête du fichier). */
    terpinoleneFreq?: number;
    /** Fréquence de l'allèle C (normal) au locus CBC — défaut 0,85
     * (~2-3% de cc/"CBC dominant"/chimiotype VI à l'équilibre, voir
     * l'en-tête du fichier). Locus indépendant de B/O/P : tiré
     * aléatoirement même quand le chimiotype choisi n'est pas VI (un
     * fondateur "chimiotype I" peut donc, rarement, se révéler cc et
     * afficher en réalité le chimiotype VI — exactement comme un trait
     * récessif rare peut être ignoré du sélectionneur). Sans effet si
     * `opts.chemotype === 'VI'` (alors forcé homozygote cc). */
    cbcFreq?: number;
    /** Locus propyl/pentyl — voir l'en-tête du fichier. true = fondateur
     * homozygote récessif pr/pr (série "varin" : THCV/CBDV/CBGV/CBCV à
     * la place de THC/CBD/CBG/CBC), défaut false (voie pentyl normale). */
    propylVariant?: boolean;
    /** Marque une fondatrice femelle comme obtenue par retournement
     * chimique (produit du pollen à la place d'un mâle) — voir la doc
     * du champ `reversedFemale` sur `Individual`. Ignoré si `sex` !== 'F'. */
    reversedFemale?: boolean;
    strainInfo?: StrainInfo;
    presetLabel?: string;
  }): Individual {
    // Le locus B reste défini même pour un fondateur IV/V (masqué tant
    // que oo/pp est présent) : un B hétérozygote neutre par défaut,
    // pour que le potentiel THC/CBD sous-jacent puisse "réapparaître"
    // si un jour le fondateur est croisé avec un porteur compatible et
    // que la descendance redevient OO/PP — cohérent avec le principe
    // de récessivité déjà utilisé pour le locus de pigmentation.
    const bPair: [BAllele, BAllele] =
      opts.chemotype === 'I'
        ? ['BT', 'BT']
        : opts.chemotype === 'III'
          ? ['BD', 'BD']
          : ['BT', 'BD'];
    const oPair: [SynthaseAllele, SynthaseAllele] = opts.chemotype === 'IV' || opts.chemotype === 'V' ? ['o', 'o'] : ['O', 'O'];
    const pPair: [PathwayAllele, PathwayAllele] = opts.chemotype === 'V' ? ['p', 'p'] : ['P', 'P'];
    // Locus C — indépendant de B/O/P (voir l'en-tête du fichier) :
    // forcé cc si le chimiotype VI est explicitement choisi, sinon
    // tiré aléatoirement selon `cbcFreq` (comme le terpinolène), donc
    // pas garanti CC pur pour les autres chimiotypes.
    const cPair: [CbcAllele, CbcAllele] =
      opts.chemotype === 'VI' ? ['c', 'c'] : this.randomCbcPair(opts.cbcFreq ?? DEFAULT_CBC_C_FREQ);
    const sexPair: [string, string] = opts.sex === 'F' ? ['X', 'X'] : ['X', 'Y'];
    const pigmentPair: [PigmentAllele, PigmentAllele] = opts.violet ? ['v', 'v'] : ['V', 'V'];
    const propylPair: [PropylAllele, PropylAllele] = opts.propylVariant ? ['pr', 'pr'] : ['Pe', 'Pe'];
    const B = this.shufflePair(bPair);
    const O = this.shufflePair(oPair);
    const P = this.shufflePair(pPair);
    const C = this.shufflePair(cPair);
    const PROPYL = this.shufflePair(propylPair);
    const vigorHapA = this.randomHaplotype('vigor', opts.vigorFreq ?? 0.5);
    const vigorHapB = this.randomHaplotype('vigor', opts.vigorFreq ?? 0.5);
    const heightHapA = this.randomHaplotype('height', opts.heightFreq ?? 0.5);
    const heightHapB = this.randomHaplotype('height', opts.heightFreq ?? 0.5);
    const coldHapA = this.randomHaplotype('cold', opts.coldFreq ?? 0.5);
    const coldHapB = this.randomHaplotype('cold', opts.coldFreq ?? 0.5);
    const sunHapA = this.randomHaplotype('sun', opts.sunFreq ?? 0.5);
    const sunHapB = this.randomHaplotype('sun', opts.sunFreq ?? 0.5);
    const moldHapA = this.randomHaplotype('mold', opts.moldFreq ?? 0.5);
    const moldHapB = this.randomHaplotype('mold', opts.moldFreq ?? 0.5);
    const terpinolene = this.randomTerpinolenePair(opts.terpinoleneFreq ?? DEFAULT_TERPINOLENE_T_FREQ);
    const myrceneHapA = this.randomHaplotype('myrcene');
    const myrceneHapB = this.randomHaplotype('myrcene');
    const limoneneHapA = this.randomHaplotype('limonene');
    const limoneneHapB = this.randomHaplotype('limonene');
    const pineneHapA = this.randomHaplotype('pinene');
    const pineneHapB = this.randomHaplotype('pinene');
    const linaloolHapA = this.randomHaplotype('linalool');
    const linaloolHapB = this.randomHaplotype('linalool');
    const sesquiterpeneHapA = this.randomHaplotype('sesquiterpene');
    const sesquiterpeneHapB = this.randomHaplotype('sesquiterpene');

    return {
      id: nextId('F0'),
      generation: 0,
      parentIds: null,
      sex: opts.sex,
      autoflower: opts.autoflower ?? false,
      label: opts.label ?? '',
      B,
      O,
      P,
      C,
      PROPYL,
      SEX: sexPair,
      PIGMENT: pigmentPair,
      terpinolene,
      vigorHapA,
      vigorHapB,
      heightHapA,
      heightHapB,
      height: this.computeQuantitative(heightHapA, heightHapB),
      coldHapA,
      coldHapB,
      coldTolerance: this.computeQuantitative(coldHapA, coldHapB),
      sunHapA,
      sunHapB,
      sunTolerance: this.computeQuantitative(sunHapA, sunHapB),
      moldHapA,
      moldHapB,
      moldResistance: this.computeQuantitative(moldHapA, moldHapB),
      myrceneHapA,
      myrceneHapB,
      limoneneHapA,
      limoneneHapB,
      pineneHapA,
      pineneHapB,
      linaloolHapA,
      linaloolHapB,
      sesquiterpeneHapA,
      sesquiterpeneHapB,
      terpeneTraits: this.buildTerpeneTraits({
        myrceneHapA,
        myrceneHapB,
        limoneneHapA,
        limoneneHapB,
        pineneHapA,
        pineneHapB,
        linaloolHapA,
        linaloolHapB,
        sesquiterpeneHapA,
        sesquiterpeneHapB,
      }),
      createdAt: Date.now(),
      strainInfo: opts.strainInfo,
      presetLabel: opts.presetLabel,
      phenotype: this.computePhenotype(B, O, P, C, PROPYL),
      vigor: this.computeQuantitative(vigorHapA, vigorHapB),
      inbreedingCoefficient: 0,
      reversedFemale: opts.sex === 'F' ? Boolean(opts.reversedFemale) : false,
    };
  }

  /** Crée un fondateur à partir d'une entrée de STRAIN_PRESETS, en
   * conservant sa fiche de culture (climat, floraison, difficulté...). */
  createFromPreset(preset: StrainPreset, sex: Sex, label?: string): Individual {
    return this.createFounder({
      chemotype: preset.chemotype,
      sex,
      autoflower: preset.autoflower,
      violet: preset.violet,
      label: label ?? preset.name,
      strainInfo: preset.info,
      presetLabel: preset.name,
    });
  }

  private gamete(ind: Individual) {
    const bAllele = ind.B[this.rng() < 0.5 ? 0 : 1];
    const oAllele = ind.O[this.rng() < 0.5 ? 0 : 1];
    const pAllele = ind.P[this.rng() < 0.5 ? 0 : 1];
    const cAllele = ind.C[this.rng() < 0.5 ? 0 : 1];
    const sexAllele = ind.SEX[this.rng() < 0.5 ? 0 : 1];
    // Loci PIGMENT et PROPYL : LIÉS (voir l'en-tête du fichier et
    // PIGMENT_PROPYL_RECOMBINATION_RATE) — au lieu de deux tirages
    // indépendants, on tire UN SEUL indice de chromosome pour PIGMENT,
    // puis PROPYL suit le même indice avec probabilité (1 - taux de
    // recombinaison) ["parental"/couplé], ou l'indice opposé avec
    // probabilité = taux de recombinaison [recombinant] — c'est la
    // définition même d'une liaison génétique à une distance de carte
    // donnée, PAS une ségrégation indépendante comme tous les autres
    // loci de ce fichier.
    const pigmentIndex = this.rng() < 0.5 ? 0 : 1;
    const propylIndex = this.rng() < PIGMENT_PROPYL_RECOMBINATION_RATE ? 1 - pigmentIndex : pigmentIndex;
    const pigmentAllele = ind.PIGMENT[pigmentIndex];
    const propylAllele = ind.PROPYL[propylIndex];
    const terpinoleneAllele = ind.terpinolene[this.rng() < 0.5 ? 0 : 1];
    const vigor = this.segregateHaplotype(ind.vigorHapA, ind.vigorHapB);
    const height = this.segregateHaplotype(ind.heightHapA, ind.heightHapB);
    const cold = this.segregateHaplotype(ind.coldHapA, ind.coldHapB);
    const sun = this.segregateHaplotype(ind.sunHapA, ind.sunHapB);
    const mold = this.segregateHaplotype(ind.moldHapA, ind.moldHapB);
    const myrcene = this.segregateHaplotype(ind.myrceneHapA, ind.myrceneHapB);
    const limonene = this.segregateHaplotype(ind.limoneneHapA, ind.limoneneHapB);
    const pinene = this.segregateHaplotype(ind.pineneHapA, ind.pineneHapB);
    const linalool = this.segregateHaplotype(ind.linaloolHapA, ind.linaloolHapB);
    const sesquiterpene = this.segregateHaplotype(ind.sesquiterpeneHapA, ind.sesquiterpeneHapB);
    return {
      bAllele,
      oAllele,
      pAllele,
      cAllele,
      sexAllele,
      pigmentAllele,
      propylAllele,
      terpinoleneAllele,
      vigor,
      height,
      cold,
      sun,
      mold,
      myrcene,
      limonene,
      pinene,
      linalool,
      sesquiterpene,
    };
  }

  /** Coefficient de consanguinité approximatif du croisement A × B —
   * voir la doc de `Individual.inbreedingCoefficient`. Détecte la
   * fratrie complète/demi-fratrie et le croisement parent × descendant
   * via `parentIds`, puis ajoute la moyenne héritée des deux parents
   * (atténuée, pour éviter une accumulation exponentielle plafonnée
   * artificiellement bas) — plafonné à 0,5. */
  private inbreedingOf(parentA: Individual, parentB: Individual): number {
    const idsA = parentA.parentIds;
    const idsB = parentB.parentIds;
    const sharedParents = idsA && idsB ? idsA.filter((id) => idsB.includes(id)).length : 0;
    const isParentOffspring =
      (idsA?.includes(parentB.id) ?? false) || (idsB?.includes(parentA.id) ?? false);
    const directF = isParentOffspring ? 0.25 : sharedParents === 2 ? 0.25 : sharedParents === 1 ? 0.125 : 0;
    const inherited = ((parentA.inbreedingCoefficient ?? 0) + (parentB.inbreedingCoefficient ?? 0)) / 2;
    return Math.min(0.5, Math.max(directF, inherited * 0.5 + directF * 0.5));
  }

  cross(parentA: Individual, parentB: Individual, label = ''): Individual {
    const gA = this.gamete(parentA);
    const gB = this.gamete(parentB);
    const inbreedingCoefficient = this.inbreedingOf(parentA, parentB);
    // Dépression de consanguinité : pénalise la vigueur proportionnellement
    // au coefficient F (jusqu'à -40% de vigueur à F=0,5) — reflète le fait
    // qu'un programme qui enchaîne fratries/rétrocroisements sur une
    // lignée fermée à 2 fondateurs perd en vitalité, même quand le score
    // de sélection progresse sur les autres critères.
    const inbreedingDepression = 1 - inbreedingCoefficient * 0.8;
    const sexAlleles: [string, string] = [gA.sexAllele, gB.sexAllele];
    const sex: Sex = sexAlleles.includes('Y') ? 'M' : 'F';
    const generation = Math.max(parentA.generation, parentB.generation) + 1;
    const B: [BAllele, BAllele] = [gA.bAllele, gB.bAllele];
    const O: [SynthaseAllele, SynthaseAllele] = [gA.oAllele, gB.oAllele];
    const P: [PathwayAllele, PathwayAllele] = [gA.pAllele, gB.pAllele];
    const C: [CbcAllele, CbcAllele] = [gA.cAllele, gB.cAllele];

    return {
      id: nextId(`G${generation}`),
      generation,
      parentIds: [parentA.id, parentB.id],
      sex,
      autoflower: parentA.autoflower && parentB.autoflower,
      label,
      B,
      O,
      P,
      C,
      SEX: sexAlleles,
      PIGMENT: [gA.pigmentAllele, gB.pigmentAllele],
      PROPYL: [gA.propylAllele, gB.propylAllele],
      terpinolene: [gA.terpinoleneAllele, gB.terpinoleneAllele],
      vigorHapA: gA.vigor,
      vigorHapB: gB.vigor,
      heightHapA: gA.height,
      heightHapB: gB.height,
      height: this.computeQuantitative(gA.height, gB.height),
      coldHapA: gA.cold,
      coldHapB: gB.cold,
      coldTolerance: this.computeQuantitative(gA.cold, gB.cold),
      sunHapA: gA.sun,
      sunHapB: gB.sun,
      sunTolerance: this.computeQuantitative(gA.sun, gB.sun),
      moldHapA: gA.mold,
      moldHapB: gB.mold,
      moldResistance: this.computeQuantitative(gA.mold, gB.mold),
      myrceneHapA: gA.myrcene,
      myrceneHapB: gB.myrcene,
      limoneneHapA: gA.limonene,
      limoneneHapB: gB.limonene,
      pineneHapA: gA.pinene,
      pineneHapB: gB.pinene,
      linaloolHapA: gA.linalool,
      linaloolHapB: gB.linalool,
      sesquiterpeneHapA: gA.sesquiterpene,
      sesquiterpeneHapB: gB.sesquiterpene,
      terpeneTraits: this.buildTerpeneTraits({
        myrceneHapA: gA.myrcene,
        myrceneHapB: gB.myrcene,
        limoneneHapA: gA.limonene,
        limoneneHapB: gB.limonene,
        pineneHapA: gA.pinene,
        pineneHapB: gB.pinene,
        linaloolHapA: gA.linalool,
        linaloolHapB: gB.linalool,
        sesquiterpeneHapA: gA.sesquiterpene,
        sesquiterpeneHapB: gB.sesquiterpene,
      }),
      createdAt: Date.now(),
      phenotype: this.computePhenotype(B, O, P, C, [gA.propylAllele, gB.propylAllele]),
      vigor: Math.max(0, this.computeQuantitative(gA.vigor, gB.vigor) * inbreedingDepression),
      inbreedingCoefficient,
    };
  }

  crossMany(parentA: Individual, parentB: Individual, n: number): Individual[] {
    return Array.from({ length: n }, () => this.cross(parentA, parentB));
  }

  /** Bouturage — copie génétique exacte d'un individu (mêmes allèles à
   * tous les loci, même vigueur/hauteur/etc., même génération), avec un
   * nouvel id propre et sans parenté de croisement. Contrairement à
   * `cross()`, aucune méiose n'a lieu : c'est la pratique réelle de
   * clonage par bouture, utilisée pour figer un phénotype gagnant
   * comme mère/père permanent sans re-tirer sa génétique à chaque
   * génération. */
  cloneOf(ind: Individual, label?: string): Individual {
    return {
      ...ind,
      id: nextId(`CL${ind.generation}`),
      label: label ?? (ind.label ? `${ind.label} (clone)` : ''),
      parentIds: ind.parentIds,
      clonedFromId: ind.id,
      notes: undefined,
      createdAt: Date.now(),
    };
  }

  /** Coefficient de consanguinité de l'individu, en pourcentage (0 à
   * 50%) — voir `Individual.inbreedingCoefficient`. */
  inbreedingPercent(ind: Individual): number {
    return Math.round((ind.inbreedingCoefficient ?? 0) * 100);
  }

  chemotypeOf(ind: Individual): ChemotypeId {
    if (ind.P[0] === 'p' && ind.P[1] === 'p') return 'V';
    if (ind.C[0] === 'c' && ind.C[1] === 'c') return 'VI';
    if (ind.O[0] === 'o' && ind.O[1] === 'o') return 'IV';
    const set = new Set(ind.B);
    if (set.size === 1 && set.has('BT')) return 'I';
    if (set.size === 1 && set.has('BD')) return 'III';
    return 'II';
  }

  /** Phénotype cannabinoïde figé à la création de l'individu (voir
   * `Individual.phenotype`) — ne re-échantillonne jamais. */
  cannabinoidPhenotype(ind: Individual): CannabinoidPhenotype {
    return ind.phenotype;
  }

  /** Valeur de vigueur figée à la création de l'individu (voir
   * `Individual.vigor`) — ne re-échantillonne jamais. */
  vigorValue(ind: Individual): number {
    return ind.vigor;
  }

  /** Vigueur normalisée en pourcentage de la borne théorique de cette
   * session (0–100), pour l'affichage en jauge. */
  vigorPercent(ind: Individual): number {
    return this.percentOf('vigor', ind.vigor);
  }

  /** Hauteur normalisée en pourcentage (0–100) : bas = plante compacte,
   * haut = plante haute. Purement relatif à cette session (pas de
   * hauteur en cm — c'est un trait de sélection, pas une fiche de
   * culture). */
  heightPercent(ind: Individual): number {
    return this.percentOf('height', ind.height);
  }

  /** Résistance au froid normalisée en pourcentage (0–100). */
  coldTolerancePercent(ind: Individual): number {
    return this.percentOf('cold', ind.coldTolerance);
  }

  /** Préférence lumineuse normalisée en pourcentage (0–100) : bas =
   * tolère l'ombre, haut = a besoin de plein soleil. */
  sunTolerancePercent(ind: Individual): number {
    return this.percentOf('sun', ind.sunTolerance);
  }

  /** Résistance moisissure/oïdium normalisée en pourcentage (0–100). */
  moldResistancePercent(ind: Individual): number {
    return this.percentOf('mold', ind.moldResistance);
  }

  isAutoflowering(ind: Individual): boolean {
    return ind.autoflower;
  }

  /** Trait récessif : violet uniquement si homozygote v/v. */
  isVioletExpressed(ind: Individual): boolean {
    return ind.PIGMENT[0] === 'v' && ind.PIGMENT[1] === 'v';
  }

  /** true si l'individu porte au moins un allèle v sans l'exprimer (porteur masqué). */
  isVioletCarrier(ind: Individual): boolean {
    return !this.isVioletExpressed(ind) && ind.PIGMENT.includes('v');
  }

  /** Trait récessif : série propyl ("varin", THCV/CBDV/CBGV/CBCV)
   * uniquement si homozygote pr/pr — voir l'en-tête du fichier. */
  isVarinExpressed(ind: Individual): boolean {
    return ind.PROPYL[0] === 'pr' && ind.PROPYL[1] === 'pr';
  }

  /** true si l'individu porte au moins un allèle pr sans l'exprimer (porteur masqué). */
  isVarinCarrier(ind: Individual): boolean {
    return !this.isVarinExpressed(ind) && ind.PROPYL.includes('pr');
  }

  /** Niveau de stress nocturne (froid/lumière) en fin de floraison, tel
   * que conduit par le cultivateur — PAS une propriété héréditaire de
   * l'individu (deux clones du même plant peuvent finir très
   * différemment selon la conduite de culture), donc volontairement
   * jamais stocké sur `Individual` : seulement un paramètre transmis
   * au moment de l'affichage. */
  static readonly coldStressLevels = ['faible', 'modéré', 'fort'] as const;

  /** Interaction génotype × environnement (G×E) sur l'EXPRESSION
   * VISIBLE de la pigmentation violette — distincte de
   * `isVioletExpressed`/`isVioletCarrier`, qui restent purement
   * génétiques (potentiel héréditaire, ce sur quoi porte la sélection
   * d'un programme de reproduction). Le potentiel génétique v/v est
   * NÉCESSAIRE mais pas SUFFISANT : la synthèse d'anthocyanes qui
   * colore les fleurs en violet est documentée comme déclenchée par le
   * stress au froid (nuits fraîches) et la baisse de lumière en fin de
   * floraison — un plant v/v conduit sans ce stress peut rester
   * essentiellement vert malgré son génotype, exactement comme le
   * signale déjà la doc du locus PIGMENT plus haut dans ce fichier
   * ("la coloration violette réelle dépend de plusieurs gènes ET de la
   * température"). 'aucune' = reste vert visuellement, 'légère' =
   * teinte violette partielle, 'pleine' = pigmentation violette
   * pleinement exprimée. */
  visibleVioletExpression(ind: Individual, coldStress: (typeof BreedingEngine.coldStressLevels)[number] = 'modéré'): 'aucune' | 'légère' | 'pleine' {
    const hasAllele = ind.PIGMENT.includes('v');
    if (!hasAllele) return 'aucune'; // V/V : aucun potentiel génétique, le stress n'y change rien
    if (this.isVioletExpressed(ind)) {
      // v/v : potentiel plein, le déclenchement visuel dépend du stress subi
      if (coldStress === 'fort') return 'pleine';
      if (coldStress === 'modéré') return 'légère';
      return 'aucune';
    }
    // Vv porteur masqué : trace visuelle possible uniquement sous fort stress
    return coldStress === 'fort' ? 'légère' : 'aucune';
  }

  /** true si l'individu porte l'allèle o à l'état masqué (Oo) sans
   * exprimer le chimiotype IV (oo) — utile pour prévenir qu'un
   * rétrocroisement entre deux porteurs peut faire réapparaître le
   * CBG-dominant en F2. */
  isSynthaseCarrier(ind: Individual): boolean {
    return !(ind.O[0] === 'o' && ind.O[1] === 'o') && ind.O.includes('o');
  }

  /** true si l'individu porte l'allèle p à l'état masqué (Pp) sans
   * exprimer le chimiotype V (pp). */
  isPathwayCarrier(ind: Individual): boolean {
    return !(ind.P[0] === 'p' && ind.P[1] === 'p') && ind.P.includes('p');
  }

  /** Trait récessif : CBC dominant (chimiotype VI, juvénilité
   * prolongée) uniquement si homozygote c/c — voir l'en-tête du
   * fichier (de Meijer et al., 2009). */
  isCbcDominant(ind: Individual): boolean {
    return ind.C[0] === 'c' && ind.C[1] === 'c';
  }

  /** true si l'individu porte l'allèle c à l'état masqué (Cc) sans
   * exprimer le chimiotype VI (cc) — même logique que
   * `isVioletCarrier`/`isPathwayCarrier`. */
  isCbcCarrier(ind: Individual): boolean {
    return !this.isCbcDominant(ind) && ind.C.includes('c');
  }

  /** Trait récessif rare : terpinolène dominant uniquement si
   * homozygote t/t — voir l'en-tête du fichier (distribution bimodale
   * documentée, ~14% des cultivars). */
  isTerpinoleneDominant(ind: Individual): boolean {
    return ind.terpinolene[0] === 't' && ind.terpinolene[1] === 't';
  }

  /** true si l'individu porte l'allèle t à l'état masqué (Tt) sans
   * exprimer le profil terpinolène-dominant (tt) — même logique que
   * `isVioletCarrier`. */
  isTerpinoleneCarrier(ind: Individual): boolean {
    return !this.isTerpinoleneDominant(ind) && ind.terpinolene.includes('t');
  }

  /**
   * Profil terpénique (chemovar) d'un individu — pourcentages relatifs
   * dérivés des traits terpéniques figés à la création (voir
   * `Individual.terpeneTraits`), fonction pure du génotype (aucun
   * nouvel échantillonnage aléatoire à chaque appel, comme
   * `cannabinoidPhenotype`). Voir l'en-tête du fichier pour le modèle
   * scientifique : caryophyllène/humulène dérivent du même trait
   * "sesquiterpene" (ratio fixe ~2:1, enzyme TPS9 partagée) ; le
   * terpinolène domine fortement en tt (trait récessif rare) et reste
   * quasi nul sinon ; myrcène/limonène/pinène/linalol suivent
   * directement leurs traits polygéniques respectifs.
   */
  terpeneProfile(ind: Individual): TerpeneProfile {
    const traits = ind.terpeneTraits;
    const terpinoleneDominant = this.isTerpinoleneDominant(ind);
    // Part du terpinolène dans le mélange : dominant chez les tt
    // (~40–65%, modulée par le trait sesquiterpène pour varier d'un
    // individu tt à l'autre sans re-tirer de nombre aléatoire), quasi
    // nul (<1%) sinon.
    const terpinolenePercent = terpinoleneDominant ? 40 + traits.sesquiterpene * 25 : 0.3 + traits.sesquiterpene * 0.4;

    // Poids relatifs des 6 autres composés, avant normalisation sur le
    // reliquat (100% - terpinolène) : les 4 monoterpènes suivent
    // directement leurs traits (0–1), caryophyllène/humulène dérivent
    // du trait "sesquiterpene" dans un ratio fixe 2:1.
    const weights: Record<Exclude<TerpeneKey, 'terpinolene'>, number> = {
      myrcene: traits.myrcene,
      limonene: traits.limonene,
      pinene: traits.pinene,
      linalool: traits.linalool,
      caryophyllene: traits.sesquiterpene * 2,
      humulene: traits.sesquiterpene * 1,
    };
    const weightSum = Object.values(weights).reduce((a, b) => a + b, 0) || 1;
    const remaining = 100 - terpinolenePercent;
    const round1 = (x: number) => Math.round(x * 10) / 10;

    const percents: Record<TerpeneKey, number> = {
      myrcene: round1((weights.myrcene / weightSum) * remaining),
      limonene: round1((weights.limonene / weightSum) * remaining),
      pinene: round1((weights.pinene / weightSum) * remaining),
      linalool: round1((weights.linalool / weightSum) * remaining),
      caryophyllene: round1((weights.caryophyllene / weightSum) * remaining),
      humulene: round1((weights.humulene / weightSum) * remaining),
      terpinolene: round1(terpinolenePercent),
    };

    const dominantTerpenes = (Object.entries(percents) as Array<[TerpeneKey, number]>)
      .filter(([, pct]) => pct >= TERPENE_DOMINANCE_THRESHOLD)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 4)
      .map(([key]) => key);

    return {
      myrcenePercent: percents.myrcene,
      limonenePercent: percents.limonene,
      pinenePercent: percents.pinene,
      linaloolPercent: percents.linalool,
      caryophyllenePercent: percents.caryophyllene,
      humulenePercent: percents.humulene,
      terpinolenePercent: percents.terpinolene,
      terpinoleneDominant,
      dominantTerpenes,
    };
  }

  /**
   * Libellé court "chemovar" : cannabinoïde(s) dominant(s) du
   * chemotype + terpènes dominants (ex. "THC · Myrcène, Limonène").
   * `terpeneLabel` permet d'injecter une traduction (ex. `tEnum`) pour
   * chaque clé `TerpeneKey` ; sans lui, retombe sur des libellés
   * français par défaut (même convention que `CHEMOTYPES.label`).
   */
  chemovarLabel(ind: Individual, terpeneLabel?: (key: TerpeneKey) => string): string {
    const defaultLabels: Record<TerpeneKey, string> = {
      myrcene: 'Myrcène',
      limonene: 'Limonène',
      pinene: 'Pinène',
      linalool: 'Linalol',
      caryophyllene: 'Caryophyllène',
      humulene: 'Humulène',
      terpinolene: 'Terpinolène',
    };
    const label = terpeneLabel ?? ((key: TerpeneKey) => defaultLabels[key]);

    const chemotype = this.chemotypeOf(ind);
    const cannabinoidPart: Record<ChemotypeId, string> = {
      I: 'THC',
      II: 'THC/CBD',
      III: 'CBD',
      IV: 'CBG',
      V: '—',
      VI: 'CBC',
    };
    const dominant = this.terpeneProfile(ind).dominantTerpenes as TerpeneKey[];
    const terpenePart = dominant.length ? dominant.map(label).join(', ') : '—';
    return `${cannabinoidPart[chemotype]} · ${terpenePart}`;
  }

  /** Code génotype compact pour l'UI — voir `genotypeCode` (fonction
   * autonome ci-dessous, exposée aussi comme méthode pour les endroits
   * où `engine` est déjà à portée). */
  genotypeCode(ind: Individual): string {
    return genotypeCode(ind);
  }
}

/** Code génotype compact pour l'UI : "BT/BD" pour un chimiotype
 * I/II/III classique, complété par "· oo"/"· Oo" ou "· pp"/"· Pp"
 * seulement quand le locus O ou P s'écarte de l'homozygote fonctionnel
 * — pour rendre visible la cause d'un chimiotype IV/V (ou un portage
 * masqué) sans surcharger l'affichage du cas courant. Fonction pure
 * (ne dépend d'aucun état du moteur), exposée aussi bien en autonome
 * qu'en méthode `BreedingEngine.genotypeCode` par confort d'appel. */
export function genotypeCode(ind: Individual): string {
  const parts = [`${ind.B[0]}/${ind.B[1]}`];
  if (ind.O.includes('o')) parts.push(ind.O[0] === 'o' && ind.O[1] === 'o' ? 'oo' : 'Oo');
  if (ind.P.includes('p')) parts.push(ind.P[0] === 'p' && ind.P[1] === 'p' ? 'pp' : 'Pp');
  if (ind.C.includes('c')) parts.push(ind.C[0] === 'c' && ind.C[1] === 'c' ? 'cc' : 'Cc');
  // Locus Terpinolène — même logique que O/P : suffixe ajouté seulement
  // si l'individu n'est pas homozygote T/T (porteur Tt ou dominant tt).
  if (ind.terpinolene.includes('t')) parts.push(ind.terpinolene[0] === 't' && ind.terpinolene[1] === 't' ? 'tt' : 'Tt');
  // Locus propyl/pentyl — même logique : suffixe ajouté seulement si
  // l'individu n'est pas homozygote Pe/Pe (porteur Pe-pr ou pr/pr).
  if (ind.PROPYL.includes('pr')) parts.push(ind.PROPYL[0] === 'pr' && ind.PROPYL[1] === 'pr' ? 'pr-pr' : 'Pe-pr');
  return parts.join(' · ');
}
